fn validate(n: Int) -> Result[Int, Str] {
  if n < 0 { return Err("negative number"); }
  if n > 100 { return Err("too large"); }
  return Ok(n);
}

fn process(n: Int) -> Int {
  return validate(n)
    .map(|x| x * x)
    .map_err(|e| "Validation: " + e)
    .unwrap_or(0);
}

fn main() -> Int {
  return process(10);
}
